def top_k(lst, k):
    sort = []
    while lst: 
        biggest = lst[0]
        for element in lst:
            if element > biggest:
                biggest = element
        lst.remove(biggest)
        sort.append(biggest)
    return sort[:k]

def top_k(lst, k):

    if lst == []:
        return lst

    lower = []
    while lst:
        higher = lst[0]
        for plist in lst:
            if plist > higher:
                higher = plist
        lst.remove(higher)
        lower.append(higher)
    return lower[:k]

