def top_k(lst, k):
    def insertion_sort(lst):
        for i in range(len(lst)):
            if i == 0: continue
            else:
                while i > 0:
                    if lst[i] < lst[i-1]:
                        lst[i], lst[i-1] = lst[i-1], lst[i]
                        i -= 1
                    else: i = 0

    insertion_sort(lst)
    lst.reverse()
    return lst[:k]
    pass

def top_k(lst, k):

    newlst = []
    for i in range((k+1) - 1):
        newlst.append(max(lst))
        lst.remove(max(lst))
    return newlst

